// AUTO-GENERATED by scripts/bake-effect-units.ts from Reference/XML/Infos.
// Do not edit by hand — re-run `npm run bake:effect-units`.
//
// What a general's traits confer on the unit they lead, as
// `HelpText.buildMakeGeneralLine` (HelpText.cs:4579) states it. Read
// through `$lib/game-detail/unit-general` (the numbers) and
// `$lib/game-detail/effect-unit-help` (the text), never directly.

/** One grouped run of `<Pair>` names that share a value. */
export interface EffectUnitValueGroup {
	readonly names: readonly string[];
	readonly value: number;
}

/** One yield a kill pays. The game's line shows the glyph, not the name. */
export interface EffectUnitYield {
	readonly yieldType: string;
	/** The game's yield name, for the glyph's accessible name. */
	readonly name: string;
	readonly value: number;
}

/** What an effect unit applies to the units it fights. */
export interface EffectUnitApply {
	/**
	 * The `TEXT_HELPTEXT_EFFECT_UNIT_APPLIES*` key `buildEffectUnitHelp`
	 * picks from the payload and the duration, resolved at bake time.
	 */
	readonly template: string;
	/** The applied effect unit's own display name. */
	readonly effectUnit: string;
	/** 0 means until the start of the target's own turn. */
	readonly turns: number;
	readonly adjacentOnly: boolean;
}

export interface GeneralEffectUnit {
	/** The game's own name, from `<GenderedName>` — never formatEnum. */
	readonly name: string;
	/**
	 * True when a trait (or `LEADER_GENERAL_EFFECT_UNIT`) names it directly,
	 * which is what `buildMakeGeneralLine` calls `buildEffectUnitHelp` on.
	 * False for one reached only through a parent's `AdjacentEffectUnit` or
	 * `aeEffectUnitUnlock`: its numbers and its name are used, its clauses
	 * are not.
	 */
	readonly direct: boolean;
	/**
	 * The unit types the display gate `Game.isEffectUnitValid`
	 * (Game.cs:14409) lets it land on, of the ones a general can lead.
	 * Absent means every one of them — so an unlisted unit type on a gated
	 * entry renders nothing rather than claiming an effect the game denies.
	 */
	readonly validUnits?: readonly string[];
	// ── The six the general line folds into its own totals ──
	readonly strengthModifier?: number;
	readonly attackModifier?: number;
	readonly perLevelAttackModifier?: number;
	readonly defenseModifier?: number;
	readonly criticalChance?: number;
	readonly movementExtra?: number;
	// ── Clause columns, in buildEffectUnitHelp's own order ──
	readonly fatigueExtra?: number;
	readonly visionExtra?: number;
	readonly revealExtra?: number;
	readonly rangeExtra?: number;
	readonly actionsExtra?: number;
	readonly homeModifier?: number;
	readonly connectedAttackModifier?: number;
	readonly urbanAttackModifier?: number;
	readonly damagedUsModifier?: number;
	readonly damagedThemModifier?: number;
	readonly vsGeneralModifier?: number;
	readonly flankingAttackModifier?: number;
	readonly adjacentSameModifier?: number;
	readonly healExtra?: number;
	readonly zoc?: true;
	readonly rout?: true;
	readonly stun?: true;
	readonly lastStand?: true;
	readonly criticalImmune?: true;
	readonly healKill?: true;
	readonly healNeutral?: true;
	readonly launchOffensive?: true;
	readonly generalHopping?: true;
	readonly buildRoad?: true;
	readonly meleeCounterPercent?: number;
	/** Height and vegetation runs, which share the FIGHT_FROM clause. */
	readonly fightFrom?: readonly EffectUnitValueGroup[];
	/** One line each, in yield order — these clauses do not group. */
	readonly militaryKillYield?: readonly EffectUnitYield[];
	readonly vsUnitTrait?: readonly (EffectUnitValueGroup & {
		readonly kind: "strength" | "attack" | "defense";
	})[];
	/** Terrain, height and vegetation names the unit hides in. */
	readonly hiddenIn?: readonly string[];
	/** The adjacent-aura effect unit's display name. */
	readonly adjacentEffectUnit?: string;
	readonly attackApply?: EffectUnitApply;
	/** The self-applied effect unit's display name. */
	readonly selfApply?: string;
}

/** A trait that confers effect units on a unit its holder leads. */
export interface GeneralTrait {
	/**
	 * `<GeneralEffectUnit>`, then that entry's `aeEffectUnitUnlock` and
	 * `AdjacentEffectUnit` — the one hop `getGeneralEffectUnits`
	 * (Character.cs:10578) takes.
	 */
	readonly general?: readonly string[];
	/** `<LeaderEffectUnit>` — only for a general who is their own leader. */
	readonly leader?: readonly string[];
}

